package app.canada.walmart;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import android.os.Looper;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowAlertDialog;import java.util.*;import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=35)
public class ToolsRegressionTest {
 Activity a;FrameLayout root;
 @Before public void setup(){a=Robolectric.buildActivity(Activity.class).setup().get();root=new FrameLayout(a);a.setContentView(root);HistoryStore.data(a).edit().clear().commit();HistoryStore.meta(a).edit().clear().commit();ToolSettings.prefs(a).edit().clear().commit();PatchStatus.installed.clear();RuntimeStats.clear();AdCleaner.candidates.clear();}
 void save(String k,String name,long cents){HistoryStore.record(a,k,name,"Store A","seller",cents);}
 View find(View v,String text){if(v instanceof TextView&&text.equals(((TextView)v).getText().toString()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=find(((ViewGroup)v).getChildAt(i),text);if(found!=null)return found;}return null;}
 View find(String text){return find(ShadowAlertDialog.getLatestAlertDialog().getWindow().getDecorView(),text);}
 @Test public void sparkyEntryOpensToolsAndAllMainSectionsAreReachable(){PatchStatus.open(root);for(String s:new String[]{"Price history · search, trends and drops","Watchlist · favourites and target prices","Patch controls","Shopping tools","Export, backup and restore","Diagnostics and installed patches","Feature guide"})assertNotNull(s,find(s));assertEquals(Integer.valueOf(1),RuntimeStats.countSnapshot().get("Patch tools opened"));}
 @Test public void floatingShortcutStopsNativeClick(){ImageButton button=new ImageButton(a);root.addView(button);final int[] nativeClicks={0};button.setOnClickListener(v->nativeClicks[0]++);SparkyReplacement.fab(root);Shadows.shadowOf(Looper.getMainLooper()).idle();button.performClick();assertEquals(0,nativeClicks[0]);assertEquals("Patch tools",button.getContentDescription());assertNotNull(ShadowAlertDialog.getLatestAlertDialog());}
 @Test public void sparkyNudgeDoesNotReturnWhenAdsAreEnabled(){View v=new View(a);root.addView(v,new FrameLayout.LayoutParams(200,100));SparkyReplacement.suppress(v);ToolSettings.set(a,"hide_ads",false);AdCleaner.refresh();assertEquals(View.GONE,v.getVisibility());v.setVisibility(View.VISIBLE);Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(View.GONE,v.getVisibility());}
 @Test public void liveAdSwitchRestoresAndRehidesExistingContainer(){View v=new View(a);root.addView(v,new FrameLayout.LayoutParams(200,100));AdCleaner.dedicated(v);assertEquals(0,v.getLayoutParams().height);ToolSettings.set(a,"hide_ads",false);AdCleaner.refresh();assertEquals(View.VISIBLE,v.getVisibility());assertEquals(100,v.getLayoutParams().height);ToolSettings.set(a,"hide_ads",true);AdCleaner.refresh();assertEquals(View.GONE,v.getVisibility());}
 @Test public void constructorHiddenAdCapturesLayoutAssignedLater(){View v=new View(a);AdCleaner.dedicated(v);v.setLayoutParams(new FrameLayout.LayoutParams(240,90));((AdCleaner.Hidden)v.getTag(AdCleaner.STATE)).collapse();ToolSettings.set(a,"hide_ads",false);AdCleaner.refresh();assertEquals(240,v.getLayoutParams().width);assertEquals(90,v.getLayoutParams().height);}
 @Test public void controlsSwitchesActuallyPersistAndApply(){PatchStatus.ads();ToolsPanel.controls(a);Switch s=(Switch)find("Hide banner and carousel ads");assertTrue(s.isChecked());s.setChecked(false);assertFalse(ToolSettings.enabled(a,"hide_ads"));assertTrue(ToolSettings.enabled(a,"hide_sponsored"));}
 @Test public void uninstalledControlsAreNotPresentedAsWorking(){ToolsPanel.controls(a);assertNull(find("Hide banner and carousel ads"));assertNotNull(find("Ad-hiding patch is not installed in this APK."));}
 @Test public void recordingMasterAndSourceSwitchesAreIndependent(){assertTrue(ToolSettings.record(a,false));ToolSettings.set(a,"record_browse",false);assertTrue(ToolSettings.record(a,false));assertFalse(ToolSettings.record(a,true));ToolSettings.set(a,"record",false);assertFalse(ToolSettings.record(a,false));}
 @Test public void historySearchMatchesStoreAndFavorites(){save("p_a","Apples",200);save("p_b","Bread",300);HistoryStore.meta(a).edit().putBoolean("p_b_favorite",true).apply();assertEquals(Arrays.asList("p_b"),HistoryTools.filtered(a,"bread",0,false,false,false));assertEquals(2,HistoryTools.filtered(a,"store a",0,false,false,false).size());assertEquals(Arrays.asList("p_b"),HistoryTools.filtered(a,"",0,true,false,false));}
 @Test public void targetsUseOnlyLatestSavedPrice(){save("p_a","Apples",600);HistoryStore.meta(a).edit().putLong("p_a_target",500).apply();assertFalse(HistoryTools.targetMet(a,"p_a"));save("p_a","Apples",450);assertTrue(HistoryTools.targetMet(a,"p_a"));assertEquals(Arrays.asList("p_a"),HistoryTools.filtered(a,"",0,false,true,false));}
 @Test public void priceDropFilterAndSummaryUsePreviousDifferentObservation(){save("p_a","Apples",600);save("p_a","Apples",450);assertEquals(150,HistoryTools.drop(a,"p_a"));assertTrue(HistoryTools.summary(a,"p_a").contains("$4.50"));assertTrue(HistoryTools.summary(a,"p_a").contains("$6.00"));assertEquals(1,HistoryTools.filtered(a,"",2,false,false,true).size());}
 @Test public void backupRoundTripPreservesObservationsAndWatchSettings()throws Exception {save("p_a","Apples",450);HistoryStore.meta(a).edit().putBoolean("p_a_favorite",true).putLong("p_a_target",500).apply();String backup=HistoryTransfer.json(a);HistoryStore.data(a).edit().clear().commit();HistoryStore.meta(a).edit().clear().commit();assertEquals(1,HistoryTransfer.merge(a,backup));assertEquals(450,HistoryTools.current(a,"p_a"));assertTrue(HistoryStore.meta(a).getBoolean("p_a_favorite",false));assertEquals(500,HistoryStore.meta(a).getLong("p_a_target",-1));}
 @Test public void malformedImportWritesNothingEvenWhenFirstItemIsValid()throws Exception {save("p_a","Apples",450);JSONObject backup=new JSONObject(HistoryTransfer.json(a));backup.getJSONArray("items").put(new JSONObject().put("key","../../invalid"));HistoryStore.data(a).edit().clear().commit();try{HistoryTransfer.merge(a,backup.toString());fail();}catch(JSONException expected){}assertTrue(HistoryStore.keys(a).isEmpty());}
 @Test public void repeatedImportDoesNotDuplicateOrReplaceExistingPoint()throws Exception {save("p_a","Apples",450);JSONObject backup=new JSONObject(HistoryTransfer.json(a));backup.getJSONArray("items").getJSONObject(0).getJSONArray("points").getJSONArray(0).put(1,999);HistoryTransfer.merge(a,backup.toString());HistoryTransfer.merge(a,backup.toString());assertEquals(1,HistoryTransfer.points(a,"p_a").size());assertEquals(450,HistoryTools.current(a,"p_a"));}
 @Test public void fractionalCentsAreRejectedWithoutChangingStoredPrices()throws Exception {save("p_a","Apples",450);JSONObject backup=new JSONObject(HistoryTransfer.json(a));backup.getJSONArray("items").getJSONObject(0).getJSONArray("points").getJSONArray(0).put(1,999.5);try{HistoryTransfer.merge(a,backup.toString());fail();}catch(JSONException expected){}assertEquals(450,HistoryTools.current(a,"p_a"));}
 @Test public void deletingHistoryRemovesTargetsAndFavorites(){save("p_a","Apples",450);HistoryStore.meta(a).edit().putBoolean("p_a_favorite",true).putLong("p_a_target",500).apply();HistoryTransfer.remove(a,"p_a");assertTrue(HistoryStore.keys(a).isEmpty());assertFalse(HistoryStore.meta(a).contains("p_a_target"));assertFalse(HistoryStore.meta(a).contains("p_a_favorite"));}
 @Test public void csvEscapesQuotesAndSpreadsheetFormulas(){save("p_a","=SUM(1,2)\"milk",450);String csv=HistoryTransfer.csv(a);assertTrue(csv.contains("\"'=SUM(1,2)\"\"milk\""));assertTrue(csv.contains(",4.50,false,"));assertFalse(csv.contains("\n=SUM"));}
 @Test public void diagnosticsNeverIncludesSavedProductNames(){save("p_a","Secret product name",450);assertFalse(ToolsPanel.report(a).contains("Secret product name"));assertTrue(ToolsPanel.report(a).contains("Saved histories: 1"));}
 @Test public void scannerUsesNativeActivityAndPermissionFlow(){ToolsPanel.scan(a);Intent intent=Shadows.shadowOf(a).getNextStartedActivity();assertEquals("com.walmart.glass.globalscanner.views.GlobalScannerActivity",intent.getComponent().getClassName());assertTrue(intent.getBooleanExtra("extraIncludeAllHandlers",false));}
 @Test public void unitComparisonAndTaxCalculationAreExact(){assertEquals(0,new java.math.BigDecimal("0.005").compareTo(ShoppingMath.perUnit("5","500","2")));assertEquals("20.70",ShoppingMath.total("10","2","10","15").toPlainString());try{ShoppingMath.perUnit("1","0","1");fail();}catch(IllegalArgumentException expected){}try{ShoppingMath.total("1","1","101","0");fail();}catch(IllegalArgumentException expected){}}
 @Test public void calculatorCanBeUsedThroughItsUi(){ToolsPanel.calculator(a);assertNotNull(find("Calculate"));find("Calculate").performClick();assertNotNull(find("Enter valid nonnegative amounts; percentages must be 0–100."));}
 @Test public void historyDialogOpensAndTargetEditorDoesNotEraseHistory(){save("p_a","Apples",450);HistoryTools.detail(a,"p_a",null);assertNotNull(find("Set target price"));find("Set target price").performClick();assertNotNull(find("Save target"));assertEquals(1,HistoryStore.keys(a).size());}
 @Test public void checklistExportKeepsUnlinkedItemsAndDeduplicatesIds()throws Exception {com.walmart.glass.lists.domain.ListItem.ChecklistItem known=new com.walmart.glass.lists.domain.ListItem.ChecklistItem("A2"),unknown=new com.walmart.glass.lists.domain.ListItem.ChecklistItem(new com.walmart.glass.lists.domain.ListItem.ListDetailItem(null));known.checked=true;List<Object> rows=Arrays.asList(known,known,unknown);String text=ChecklistExport.render(rows,false),csv=ChecklistExport.render(rows,true);assertTrue(text.contains("Manual item"));assertTrue(text.contains("price unavailable"));assertTrue(text.contains("Unpriced, excluded: 1"));assertEquals(3,csv.split("\r\n").length);assertTrue(csv.contains(",true,"));}
}
